void vmu_anim_update(void) {
    static int sAnimFrame = 0;
    static int sFrameTimer = 0;

    // Update VMU LCD frame every 2 logic ticks (~30 FPS) for smooth forward animation
    sFrameTimer++;
    if (sFrameTimer >= 2) {
        sFrameTimer = 0;
        sAnimFrame = (sAnimFrame + 1) % VMU_ANIM_FRAME_COUNT;

        for (int i = 0; i < 8; i++) {
            maple_device_t *dev = maple_enum_type(i, MAPLE_FUNC_LCD);
            if (dev && dev->valid) {
                vmu_draw_lcd(dev, gVmuAnimFrames[sAnimFrame]);
            }
        }
    }
}
